Bước 1 (Yêu cầu 1 - Tạo 4 bảng với PK và FK):
```sql
CREATE TABLE KHACHSAN (MAKS CHAR(10) PRIMARY KEY, TENKS NVARCHAR(50), DIACHI NVARCHAR(100));
CREATE TABLE KHACH (MAKHACH CHAR(10) PRIMARY KEY, HOTEN NVARCHAR(50), DIACHI NVARCHAR(100));
CREATE TABLE PHONG (SOP CHAR(10), MAKS CHAR(10), LOAIP NVARCHAR(20), GIA INT,
    PRIMARY KEY (SOP, MAKS), FOREIGN KEY (MAKS) REFERENCES KHACHSAN(MAKS));
CREATE TABLE DATPHONG (MAKS CHAR(10), MAKHACH CHAR(10), NGAYNHAN DATE, NGAYTRA DATE, SOP CHAR(10),
    PRIMARY KEY (MAKS, MAKHACH, NGAYNHAN),
    FOREIGN KEY (SOP, MAKS) REFERENCES PHONG(SOP, MAKS),
    FOREIGN KEY (MAKHACH) REFERENCES KHACH(MAKHACH));
```

Bước 1 (Câu a - Tạo 3 bảng với PK và FK):
```sql
CREATE TABLE KHACHHANG (MAKH CHAR(8) PRIMARY KEY NOT NULL, HOTEN NVARCHAR(30) NOT NULL, SODIENTHOAI CHAR(11), COQUAN NVARCHAR(30));
CREATE TABLE NHACHOTHUE (MAN CHAR(6) PRIMARY KEY NOT NULL, DIACHI NVARCHAR(70), GIATHUE INT, TENCHUNHA NVARCHAR(30));
CREATE TABLE HOPDONG (MAN CHAR(6), MAKH CHAR(8), NGAYBATDAU DATE, NGAYKETTHUC DATE,
    PRIMARY KEY (MAN, MAKH),
    FOREIGN KEY (MAN) REFERENCES NHACHOTHUE(MAN),
    FOREIGN KEY (MAKH) REFERENCES KHACHHANG(MAKH));
```

Bước 2 (Câu b - Tạo `KHOA`, `GIANGVIEN`, `SINHVIEN`, `DETAI` kèm `CHECK`):
```sql
CREATE TABLE KHOA (MAKHOA CHAR(6) PRIMARY KEY, TENKHOA NVARCHAR(100) NOT NULL, SDT VARCHAR(11));
CREATE TABLE GIANGVIEN (MAGV CHAR(10) PRIMARY KEY, HOTENGV NVARCHAR(50) NOT NULL,
    MAKHOA CHAR(6) REFERENCES KHOA(MAKHOA));
CREATE TABLE SINHVIEN (MASV CHAR(10) PRIMARY KEY, HOTENSV NVARCHAR(50) NOT NULL,
    MAKHOA CHAR(10), NAMSINH INT CHECK (NAMSINH BETWEEN 1930 AND 10000));
CREATE TABLE DETAI (MADT CHAR(10) PRIMARY KEY, TENDT NVARCHAR(1000) NOT NULL, NAM INT,
    KINHPHI BIGINT CHECK (KINHPHI BETWEEN 0 AND 100000000000),
    KETQUA DECIMAL(3,1) CHECK (KETQUA BETWEEN 0 AND 10));
```

Bước 4 (Câu c - Sửa độ dài `MAKHOA` trong `SINHVIEN` thành 6 ký tự và bổ sung FK):
```sql
ALTER TABLE SINHVIEN ALTER COLUMN MAKHOA CHAR(6);
ALTER TABLE SINHVIEN ADD CONSTRAINT FK_SV_KHOA FOREIGN KEY (MAKHOA) REFERENCES KHOA(MAKHOA);
```

Bước 2 (Câu c - Xóa đề tài năm <= 1998 — phải xóa ở 2 bảng con `SVTHUCHIEN` và `HUONGDAN` trước do ràng buộc FK):
```sql
DELETE FROM SVTHUCHIEN WHERE MADT IN (SELECT MADT FROM DETAI WHERE NAM <= 1998);
DELETE FROM HUONGDAN WHERE MADT IN (SELECT MADT FROM DETAI WHERE NAM <= 1998);
DELETE FROM DETAI WHERE NAM <= 1998;
```

Bước 1 (Tạo các bảng thực thể độc lập `DIENVIEN`, `DAODIEN`, `THELOAI`, `NGUOIDANHGIA`):
```sql
CREATE TABLE DIENVIEN (ma_dienvien INT PRIMARY KEY, hoten NVARCHAR(50), namsinh INT, gioitinh CHAR(1));
CREATE TABLE DAODIEN (ma_daodien INT PRIMARY KEY, hoten NVARCHAR(50));
CREATE TABLE THELOAI (ma_theloai INT PRIMARY KEY, tentheloai NVARCHAR(30));
CREATE TABLE NGUOIDANHGIA (ma_ndg INT PRIMARY KEY, ten_ndg NVARCHAR(50));
```

