Bước 1 (Tạo các bảng và nhập dữ liệu mẫu — lưu ý khóa đội Bình Dương là `'BD'` đồng bộ giữa `DOI` và `CAUTHU`):
```sql
CREATE TABLE DOI (ma_doi CHAR(5) PRIMARY KEY, tendoi NVARCHAR(50), tp NVARCHAR(50), hlv NVARCHAR(50), doitruong NVARCHAR(50));
CREATE TABLE VITRICAUTHU (ma_vitri CHAR(5) PRIMARY KEY, ten_vitri NVARCHAR(30));
CREATE TABLE CAUTHU (ma_cauthu CHAR(5) PRIMARY KEY, hoten NVARCHAR(50), doi CHAR(5) REFERENCES DOI(ma_doi), vitri CHAR(5) REFERENCES VITRICAUTHU(ma_vitri));
CREATE TABLE TRANDAU (ma_trandau CHAR(5) PRIMARY KEY, ngay DATE, doi1 CHAR(5) REFERENCES DOI(ma_doi), doi2 CHAR(5) REFERENCES DOI(ma_doi), tiso VARCHAR(10));
CREATE TABLE HOSOCHANTHUONG (ma_trandau CHAR(5) REFERENCES TRANDAU(ma_trandau), ma_cauthu CHAR(5) REFERENCES CAUTHU(ma_cauthu), chanthuong NVARCHAR(100), PRIMARY KEY (ma_trandau, ma_cauthu));
```
